/* Microfix 3.8.38: cleaner group/export state + Figma-style object context menu + project arrow placement */
function syncExportAvailability(){
  const btn=document.getElementById("exportBtn");if(!btn)return;
  const active=Array.isArray(state.selected)&&state.selected.length>0;
  btn.disabled=!active;btn.setAttribute("aria-disabled",active?"false":"true");
  if(!active){const menu=document.getElementById("exportMenu");if(menu)menu.hidden=true}
}
function bcContextLabel(key){
  const dict={
    en:{properties:"Properties",group:"Group",ungroup:"Ungroup",duplicate:"Duplicate",delete:"Delete"},
    ru:{properties:"Свойства",group:"Сгруппировать",ungroup:"Разгруппировать",duplicate:"Дублировать",delete:"Удалить"},
    de:{properties:"Eigenschaften",group:"Gruppieren",ungroup:"Gruppierung aufheben",duplicate:"Duplizieren",delete:"Löschen"},
    es:{properties:"Propiedades",group:"Agrupar",ungroup:"Desagrupar",duplicate:"Duplicar",delete:"Eliminar"},
    ja:{properties:"プロパティ",group:"グループ化",ungroup:"グループ解除",duplicate:"複製",delete:"削除"},
    zh:{properties:"属性",group:"编组",ungroup:"取消编组",duplicate:"复制",delete:"删除"}
  };
  return (dict[state.language]||dict.en)[key]||key;
}
function closeObjectContextMenu(){document.getElementById("bcObjectContextMenu")?.remove()}
function openObjectContextMenu(event,obj){
  event.preventDefault();event.stopPropagation();closeObjectContextMenu();
  if(!state.selected.includes(obj.id))selectObject(obj.id,false);
  const picked=selectedObjects(),groups=[...new Set(picked.map(o=>o.group).filter(Boolean))],singleGroup=groups.length===1&&picked.every(o=>o.group===groups[0]);
  const menu=document.createElement("div");menu.id="bcObjectContextMenu";menu.className="bc-object-context-menu";
  const item=(action,label,danger=false)=>`<button type="button" data-context-action="${action}" class="${danger?"danger":""}">${label}</button>`;
  menu.innerHTML=[
    item("properties",bcContextLabel("properties")),
    picked.length>1?(singleGroup?item("ungroup",bcContextLabel("ungroup")):item("group",bcContextLabel("group"))):"",
    item("duplicate",bcContextLabel("duplicate")),
    '<i class="bc-context-separator"></i>',
    item("delete",bcContextLabel("delete"),true)
  ].join("");
  document.body.append(menu);
  const r=menu.getBoundingClientRect(),left=Math.max(8,Math.min(innerWidth-r.width-8,event.clientX)),top=Math.max(8,Math.min(innerHeight-r.height-8,event.clientY));
  menu.style.left=`${left}px`;menu.style.top=`${top}px`;
  menu.addEventListener("click",e=>{
    const action=e.target.closest("[data-context-action]")?.dataset.contextAction;if(!action)return;
    closeObjectContextMenu();
    if(action==="properties"){document.getElementById("inspector")?.classList.remove("collapsed");renderInspector();return}
    if(action==="group")groupSelection();
    if(action==="ungroup")ungroupSelection();
    if(action==="duplicate")duplicateSelection();
    if(action==="delete")deleteSelection();
  });
}
document.addEventListener("pointerdown",e=>{if(!e.target.closest("#bcObjectContextMenu"))closeObjectContextMenu()},true);
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeObjectContextMenu()},true);
(()=>{const toggle=document.getElementById("layersProjectMenuToggle"),box=toggle?.closest(".layers-project-titlebox"),title=box?.querySelector(":scope > strong");if(toggle&&box&&title)box.insertBefore(toggle,title)})();
setTimeout(syncExportAvailability,0);

/* Microfix 3.8.38: project arrow before title; no Layers group button; export only lights up with selection */
.layers-project-titlebox{grid-template-columns:18px minmax(0,1fr)!important;column-gap:4px!important}
.layers-project-titlebox>small{grid-column:1/3!important}
.layers-project-menu-toggle{grid-column:1!important;grid-row:2!important;width:18px!important;height:24px!important;border-radius:6px!important}
.layers-project-menu-toggle svg{width:11px!important;height:11px!important}
.layers-project-titlebox>strong{grid-column:2!important;grid-row:2!important;padding-right:2px!important}
#groupSelection{display:none!important}
#exportBtn:disabled{background:var(--surface-2)!important;color:var(--muted)!important;border-color:var(--line)!important;box-shadow:none!important;filter:none!important;opacity:.62!important;cursor:default!important}
#exportBtn:disabled:hover{transform:none!important;box-shadow:none!important}
.bc-object-context-menu{position:fixed;z-index:99999;min-width:190px;padding:6px;background:var(--surface);border:1px solid var(--line);border-radius:12px;box-shadow:0 16px 44px rgba(0,0,0,.28);display:grid;gap:2px}
.bc-object-context-menu button{height:34px;border:0;border-radius:8px;background:transparent;color:var(--text);text-align:left;padding:0 10px;font:inherit;font-size:12px;cursor:pointer}
.bc-object-context-menu button:hover{background:var(--surface-2)}
.bc-object-context-menu button.danger{color:#ef5b68}
.bc-context-separator{height:1px;background:var(--line);margin:4px 5px;display:block}
